import React from 'react';
import {
  LiveKitRoom,
} from '@livekit/components-react';
import '@livekit/components-styles';
import Icon from '../../components/AppIcon';
import { cn } from '../../utils/cn';
import { supabaseService } from '../../services/supabaseService';
import ConfirmationModal from '../ui/ConfirmationModal';
import { useToast } from '../../contexts/ToastContext';
import SecureVideoConference from './SecureVideoConference';

const LiveRoom = ({ sessionId, roomName, token, onLeave, onDisconnect, isHost, adminIdentity }) => {
  const { addToast } = useToast();
  const handleLeave = onLeave || onDisconnect;
  const [isRecording, setIsRecording] = React.useState(false);
  const [showEndConfirm, setShowEndConfirm] = React.useState(false);
  const [isEnding, setIsEnding] = React.useState(false);
  const [studentsMuted, setStudentsMuted] = React.useState(false);
  const [isTogglingMedia, setIsTogglingMedia] = React.useState(false);

  // Setup Realtime Channel for this specific session
  React.useEffect(() => {
    if (!roomName) return;

    const channel = supabaseService.supabase.channel(`room_${roomName.replace(/\s+/g, '_')}`);

    channel
      .on('broadcast', { event: 'SESSION_ENDED' }, () => {
        if (!isHost) {
          addToast("The host has ended this session. Redirecting...", "info");
          setTimeout(handleLeave, 2000);
        }
      })
      .on('broadcast', { event: 'MEDIA_DISABLED' }, () => {
        if (!isHost) {
          addToast("Camera and microphone have been disabled by the host.", "info");
        }
      })
      .on('broadcast', { event: 'MEDIA_ENABLED' }, () => {
        if (!isHost) {
          addToast("Camera and microphone have been re-enabled by the host.", "info");
        }
      })
      .subscribe();

    return () => {
      channel.unsubscribe();
    };
  }, [roomName, isHost, handleLeave]);

  const handleToggleRecording = async () => {
    try {
      if (!isRecording) {
        await supabaseService.startRecording(roomName);
        setIsRecording(true);
      } else {
        await supabaseService.stopRecording(roomName);
        setIsRecording(false);
      }
    } catch (err) {
      console.error("Recording error:", err);
    }
  };

  const handleToggleStudentsMedia = async () => {
    if (!adminIdentity) {
      addToast("Cannot identify admin identity.", "error");
      return;
    }
    setIsTogglingMedia(true);
    try {
      const channelName = `room_${roomName.replace(/\s+/g, '_')}`;
      if (!studentsMuted) {
        // Disable all students' camera and mic
        await supabaseService.disableAllStudentsMedia(roomName, adminIdentity);
        await supabaseService.supabase.channel(channelName).send({
          type: 'broadcast',
          event: 'MEDIA_DISABLED',
          payload: {},
        });
        setStudentsMuted(true);
        addToast("All students' camera and microphone have been disabled.", "success");
      } else {
        // Re-enable all students' camera and mic
        await supabaseService.enableAllStudentsMedia(roomName, adminIdentity);
        await supabaseService.supabase.channel(channelName).send({
          type: 'broadcast',
          event: 'MEDIA_ENABLED',
          payload: {},
        });
        setStudentsMuted(false);
        addToast("All students' camera and microphone have been re-enabled.", "success");
      }
    } catch (err) {
      console.error("Toggle media error:", err);
      addToast("Failed to toggle student media. Please try again.", "error");
    } finally {
      setIsTogglingMedia(false);
    }
  };

  const handleEndSessionRequest = () => {
    setShowEndConfirm(true);
  };

  const handleConfirmEndSession = async () => {
    setIsEnding(true);
    try {
      // 1. Notify everyone via Broadcast
      const channelName = `room_${roomName.replace(/\s+/g, '_')}`;
      await supabaseService.supabase.channel(channelName).send({
        type: 'broadcast',
        event: 'SESSION_ENDED',
        payload: { message: 'Host ended session' },
      });

      // 2. Stop recording
      if (isRecording) {
        await supabaseService.stopRecording(roomName);
      }
      
      // 3. Update database status
      if (sessionId) {
        await supabaseService.updateLiveSessionStatus(sessionId, 'ended');
      }
      
      setShowEndConfirm(false);
      handleLeave();
    } catch (err) {
      console.error("Error ending session:", err);
      setShowEndConfirm(false);
      handleLeave(); 
    } finally {
      setIsEnding(false);
    }
  };

  if (!token) {
    return (
      <div className="min-h-[400px] flex items-center justify-center bg-slate-900 rounded-3xl border-2 border-slate-800 animate-pulse">
        <div className="text-center">
          <Icon name="Loader2" className="animate-spin text-primary mx-auto mb-4" size={40} />
          <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Initializing Secure Connection...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] flex flex-col bg-[#0A0C10] overflow-hidden">
      {/* Premium Header Overlay */}
      <div className="absolute top-4 left-4 sm:top-6 sm:left-6 z-20 flex flex-wrap items-center gap-2 sm:gap-3 max-w-[90vw]">
        <div className="bg-red-600 px-2 sm:px-3 py-1 rounded-full text-[8px] sm:text-[10px] font-black text-white flex items-center gap-1.5 sm:gap-2 animate-pulse shrink-0">
          <div className="w-1 h-1 sm:w-1.5 sm:h-1.5 bg-white rounded-full" />
          LIVE
        </div>
        
        <div className="hidden xs:flex bg-black/60 backdrop-blur-xl px-3 sm:px-4 py-1 sm:py-1.5 rounded-2xl border border-white/10 text-white font-bold text-xs sm:text-sm items-center gap-2 truncate max-w-[150px] sm:max-w-none">
          <Icon name="Users" size={typeof window !== 'undefined' && window.innerWidth < 640 ? 12 : 14} className="text-primary shrink-0" />
          <span className="truncate">{roomName || 'LUC Academy Session'}</span>
        </div>

        {/* HOST CONTROLS */}
        {isHost && (
          <div className="flex items-center gap-1.5 sm:gap-2">
            <button 
              onClick={handleToggleStudentsMedia}
              disabled={isTogglingMedia}
              className={cn(
                "px-3 sm:px-4 py-1 sm:py-1.5 rounded-2xl border font-bold text-[10px] sm:text-sm transition-all flex items-center gap-1.5 sm:gap-2",
                studentsMuted 
                  ? "bg-amber-500/20 border-amber-500 text-amber-400" 
                  : "bg-white/10 border-white/10 text-white hover:bg-white/20",
                isTogglingMedia && "opacity-50 cursor-not-allowed"
              )}
            >
              {isTogglingMedia ? (
                <Icon name="Loader2" size={12} className="animate-spin" />
              ) : (
                <Icon name={studentsMuted ? "MicOff" : "Mic"} size={12} />
              )}
              <span className="hidden sm:inline">{studentsMuted ? 'STUDENTS MUTED' : 'MUTE STUDENTS'}</span>
              <span className="sm:hidden">{studentsMuted ? 'MUTED' : 'MUTE'}</span>
            </button>

            <button 
              onClick={handleToggleRecording}
              className={cn(
                "px-3 sm:px-4 py-1 sm:py-1.5 rounded-2xl border font-bold text-[10px] sm:text-sm transition-all flex items-center gap-1.5 sm:gap-2",
                isRecording 
                  ? "bg-red-600/20 border-red-600 text-red-500 animate-pulse" 
                  : "bg-white/10 border-white/10 text-white hover:bg-white/20"
              )}
            >
              <div className={cn("w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full", isRecording ? "bg-red-500" : "bg-slate-400")} />
              <span className="hidden sm:inline">{isRecording ? 'RECORDING...' : 'RECORD'}</span>
              <span className="sm:hidden">{isRecording ? 'REC' : 'REC'}</span>
            </button>

            <button 
              onClick={handleEndSessionRequest}
              className="bg-red-600 hover:bg-red-700 px-3 sm:px-4 py-1 sm:py-1.5 rounded-2xl text-white font-black text-[10px] sm:text-sm transition-all shadow-lg shadow-red-600/20 active:scale-95"
            >
              <span className="hidden sm:inline">END SESSION</span>
              <span className="sm:hidden">END</span>
            </button>
          </div>
        )}
      </div>

      <LiveKitRoom
        video={true}
        audio={true}
        token={token}
        serverUrl={import.meta.env.VITE_LIVEKIT_URL}
        connectOptions={{
            autoSubscribe: true,
            adaptiveStream: true,
            publishDefaults: {
                dtlsRetransmissions: 20,
                iceRestart: true,
            }
        }}
        data-lk-theme="default"
        onDisconnected={() => {
            // If host leaves, make sure the session is officially marked as ended
            if (isHost && sessionId) {
                supabaseService.updateLiveSessionStatus(sessionId, 'ended').catch(console.error);
            }
            handleLeave();
        }}
        onError={(err) => {
            console.error("LiveKit Error:", err);
            addToast("Connection issue detected. Attempting to recover...", "warning");
        }}
        className="flex-1"
      >
        <SecureVideoConference />
      </LiveKitRoom>

      {/* Security Watermark */}
      <div className="absolute bottom-16 sm:bottom-20 right-4 sm:right-6 opacity-10 pointer-events-none z-0">
        <div className="text-white font-black text-lg sm:text-3xl tracking-tighter italic uppercase">LUC HUB</div>
      </div>

      {/* CUSTOM CONFIRMATION MODAL */}
      <ConfirmationModal
        isOpen={showEndConfirm}
        onClose={() => setShowEndConfirm(false)}
        onConfirm={handleConfirmEndSession}
        isLoading={isEnding}
        title="End Session?"
        message="Are you sure you want to end this live session for everyone? This action cannot be undone."
        confirmText="End Meeting"
        type="danger"
        isLocal={true}
      />
    </div>
  );
};

export default LiveRoom;
